//! Reads the byte array that `fxc /Fh` writes. No Windows dependency, so it is testable anywhere.

/// Bytes of the first `const BYTE name[] = { ... };` in an `fxc /Fh` header, or `None` if the
/// array is missing or holds anything other than decimal or `0x` hex numbers. The comment block
/// fxc writes before the array, and any `//` comment inside it, are ignored.
#[allow(dead_code, reason = "used only by the Windows shader build")]
pub fn parse_fxc_header(text: &str) -> Option<Vec<u8>> {
    let decl = text.find("const BYTE")?;
    let rest = &text[decl..];
    let open = rest.find('{')?;
    let body = &rest[open + 1..];
    let close = body.find('}')?;
    let mut bytes = Vec::new();
    for line in body[..close].lines() {
        let line = line.split("//").next().unwrap_or("");
        for token in line.split(',').map(str::trim).filter(|t| !t.is_empty()) {
            let value = match token.strip_prefix("0x").or_else(|| token.strip_prefix("0X")) {
                Some(hex) => u8::from_str_radix(hex, 16),
                None => token.parse::<u8>(),
            };
            bytes.push(value.ok()?);
        }
    }
    Some(bytes)
}

/// True if `bytes` looks like a DXBC container: the magic and a full header.
#[allow(dead_code, reason = "used only by the Windows shader build")]
pub fn is_dxbc(bytes: &[u8]) -> bool {
    bytes.len() >= 32 && bytes.starts_with(b"DXBC")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample(eol: &str, hex: bool) -> String {
        let mut s = String::new();
        s.push_str("#if 0\n//\n// Generated by Microsoft (R) HLSL Shader Compiler 10.1\n");
        s.push_str("// cbuffer GlobalParams  // Offset: 0 Size: 16\n// Output signature 1 2 3\n#endif\n\n");
        s.push_str("const BYTE g_quad_vertex[] =\n{\n");
        let mut data = b"DXBC".to_vec();
        data.extend((0u8..60).map(|i| i.wrapping_mul(7)));
        for chunk in data.chunks(6) {
            let items: Vec<String> = chunk
                .iter()
                .map(|b| if hex { format!("0x{b:02X}") } else { format!("{b:>6}") })
                .collect();
            s.push_str(&format!("    {},\n", items.join(", ")));
        }
        s.push_str("};\n");
        s.replace('\n', eol)
    }

    #[test]
    fn decimal_lf_crlf_and_hex() {
        for (eol, hex) in [("\n", false), ("\r\n", false), ("\n", true), ("\r\n", true)] {
            let bytes = parse_fxc_header(&sample(eol, hex)).unwrap();
            assert_eq!(bytes.len(), 64);
            assert!(is_dxbc(&bytes));
            assert_eq!(&bytes[..4], &[68, 88, 66, 67]);
            assert_eq!(bytes[5], 7);
        }
    }

    #[test]
    fn inline_comment_and_no_trailing_comma() {
        let t = "const BYTE x[] = {\n 68, 88, // DXBC 99\n 66, 67 };";
        assert_eq!(parse_fxc_header(t).unwrap(), b"DXBC");
    }

    #[test]
    fn rejects_bad_input() {
        assert_eq!(parse_fxc_header(""), None);
        assert_eq!(parse_fxc_header("const BYTE x[] =\n{\n};").unwrap(), Vec::<u8>::new());
        assert_eq!(parse_fxc_header("const BYTE x[] = { 1, 300 };"), None);
        assert_eq!(parse_fxc_header("const BYTE x[] = { 1, zz };"), None);
        assert!(!is_dxbc(&[]));
        assert!(!is_dxbc(&[1u8; 64]));
        assert!(!is_dxbc(b"DXBC"));
    }
}
